CREATE TABLE audit_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT, workspace_id UUID, actor_id UUID, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id UUID NOT NULL, correlation_id UUID NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', previous_hash TEXT, integrity_hash TEXT UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE event_outbox (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT, workspace_id UUID, aggregate_type TEXT NOT NULL, aggregate_id UUID NOT NULL, event_type TEXT NOT NULL, event_version INTEGER NOT NULL, payload JSONB NOT NULL, correlation_id UUID NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
CREATE INDEX event_outbox_unpublished_idx ON event_outbox(occurred_at) WHERE published_at IS NULL;
CREATE OR REPLACE FUNCTION current_workspace_id() RETURNS UUID LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.workspace_id', true),'')::uuid $$;
CREATE OR REPLACE FUNCTION current_actor_id() RETURNS UUID LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.actor_id', true),'')::uuid $$;
CREATE OR REPLACE FUNCTION has_active_workspace_membership(target UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM workspace_memberships WHERE workspace_id=target AND user_id=current_actor_id() AND status='ACTIVE') $$;
ALTER TABLE workspace_memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE organizations ENABLE ROW LEVEL SECURITY; ALTER TABLE organization_units ENABLE ROW LEVEL SECURITY; ALTER TABLE permission_grants ENABLE ROW LEVEL SECURITY; ALTER TABLE parties ENABLE ROW LEVEL SECURITY; ALTER TABLE verification_results ENABLE ROW LEVEL SECURITY; ALTER TABLE beneficiary_account_references ENABLE ROW LEVEL SECURITY; ALTER TABLE policy_acceptances ENABLE ROW LEVEL SECURITY; ALTER TABLE legal_holds ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_authorized_workspace ON workspace_memberships USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY organizations_authorized_workspace ON organizations USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY units_authorized_workspace ON organization_units USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY grants_authorized_workspace ON permission_grants USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY parties_authorized_workspace ON parties USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY verification_authorized_workspace ON verification_results USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY beneficiaries_authorized_workspace ON beneficiary_account_references USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY acceptances_authorized_workspace ON policy_acceptances USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE POLICY holds_authorized_workspace ON legal_holds USING (workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));
CREATE OR REPLACE FUNCTION prevent_append_only_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only table'; END $$;
CREATE TRIGGER audit_records_append_only BEFORE UPDATE OR DELETE ON audit_records FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();
CREATE TRIGGER verification_results_append_only BEFORE UPDATE OR DELETE ON verification_results FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();
